from __future__ import annotations

from api.operator_console_queue import CONSOLE_HTML_V26

BOUNDED_SCRIPT = r"""
<style>
.bound-panel{margin-top:14px;background:#fff;border:1px solid #dce9f8;border-radius:18px;padding:18px;box-shadow:0 12px 34px rgba(11,47,97,.05)}.bound-form{display:grid;grid-template-columns:1fr 1fr;gap:10px}.bound-form input,.bound-form select,.bound-form textarea{width:100%;border:1px solid #cbdced;border-radius:10px;padding:10px;font:inherit;background:#fff}.bound-form textarea{grid-column:1/-1;min-height:86px;resize:vertical}.bound-form .full{grid-column:1/-1}.bound-form button{grid-column:1/-1;border:0;border-radius:10px;padding:12px;background:#0b2f61;color:#fff;font-weight:800;cursor:pointer}.bound-form button:disabled{opacity:.55;cursor:not-allowed}.bound-meta{font-size:13px;color:#63758d;margin-bottom:12px}.bound-status{min-height:20px;margin-top:10px;font-size:13px}.bound-status.ok{color:#147a46}.bound-status.err{color:#b42318}@media(max-width:620px){.bound-form{grid-template-columns:1fr}}
</style>
<script>
async function loadBoundedActionControl(recordId){const view=document.getElementById('view');if(!view||!recordId)return;let box=document.getElementById('bounded-action-control');if(!box){box=document.createElement('section');box.id='bounded-action-control';box.className='bound-panel';const timeline=view.querySelector('.timeline');if(timeline)view.insertBefore(box,timeline);else view.appendChild(box)}box.innerHTML='<h3>Bounded Action Draft</h3><div class="muted">Checking current review event…</div>';try{const r=await fetch('/operator/api/cases/'+encodeURIComponent(recordId)+'/action-context',{credentials:'same-origin'});if(r.status===401){location.href='/operator/login';return}if(!r.ok)throw new Error('action context unavailable');const d=await r.json();if(!d.current_review_event){box.innerHTML='<h3>Bounded Action Draft</h3><div class="muted">Record a human review event first.</div>';return}if(!d.can_prepare_bounded_action){box.innerHTML=`<h3>Bounded Action Draft</h3><div class="muted">Current review decision: ${esc(d.current_review_event.decision)}. No bounded action is permitted from this decision.</div>`;return}const existing=d.existing_latest_action?`Latest draft: ${esc(d.existing_latest_action.action_kind)} · ${esc(d.existing_latest_action.state)} · ${esc(d.existing_latest_action.action_packet_id)}`:'No bounded action draft exists yet.';const kinds=d.allowed_action_kinds.map(x=>`<option value="${esc(x)}">${esc(x.replaceAll('_',' '))}</option>`).join('');box.innerHTML=`<h3>Bounded Action Draft</h3><div class="bound-meta">Review decision: <strong>${esc(d.current_review_event.decision)}</strong><br>${existing}<br>Preparing a newer draft makes any older draft for this review event stale.</div><form id="bounded-action-form" class="bound-form"><select id="bound-kind">${kinds}</select><input id="bound-cap" placeholder="Target capability (optional)"><textarea id="bound-objective" placeholder="Objective" required></textarea><textarea id="bound-scope" placeholder="Scope / boundaries (optional)"></textarea><button id="bound-submit">Prepare bounded action packet</button></form><div id="bound-status" class="bound-status"></div>`;box.querySelector('#bounded-action-form').addEventListener('submit',async(e)=>{e.preventDefault();const status=box.querySelector('#bound-status');const btn=box.querySelector('#bound-submit');status.textContent='';status.className='bound-status';btn.disabled=true;try{const csrf=await loadConsoleCsrf();const body={action_kind:box.querySelector('#bound-kind').value,objective:box.querySelector('#bound-objective').value,scope:box.querySelector('#bound-scope').value,target_capability:box.querySelector('#bound-cap').value};const rr=await fetch('/operator/api/review-events/'+encodeURIComponent(d.current_review_event.event_id)+'/bounded-action',{method:'POST',headers:{'content-type':'application/json','x-vmi-csrf':csrf},credentials:'same-origin',body:JSON.stringify(body)});if(!rr.ok){const x=await rr.json().catch(()=>({}));throw new Error(x.detail||'Bounded action rejected')}const x=await rr.json();status.textContent='Prepared '+x.packet.action_kind+' packet '+x.packet.action_packet_id+'. No approval or execution authority was created.';status.className='bound-status ok';setTimeout(()=>loadCase(recordId),300)}catch(err){status.textContent=String(err.message||err);status.className='bound-status err'}finally{btn.disabled=false}})}catch(_){box.innerHTML='<h3>Bounded Action Draft</h3><div class="muted">Action context unavailable.</div>'}}
const _v26LoadCase=loadCase;loadCase=async function(id){await _v26LoadCase(id);await loadBoundedActionControl(id)};setTimeout(()=>{if(selected)loadBoundedActionControl(selected)},900);
</script>
"""

CONSOLE_HTML_V28 = CONSOLE_HTML_V26.replace("</body>", BOUNDED_SCRIPT + "</body>")
